#!/bin/bash
# Translates shaders/edit.wgsl (the source of truth, loaded as-is by the web app) into Metal Shading
# Language for the server, embedded in a Swift file that is committed — building the server needs no
# naga. Run after every change to the WGSL; a server test fails while the generated file is stale.
set -euo pipefail
cd "$(dirname "$0")/.."
NAGA=${NAGA:-$(command -v naga || echo "$HOME/.cargo/bin/naga")}
[ -x "$NAGA" ] || { echo "naga not found: cargo install naga-cli" >&2; exit 1; }
src=shaders/edit.wgsl
out=server/Sources/PhotoCore/Editing/EditShaders.generated.swift
tmp=$(mktemp -t edit).metal
"$NAGA" "$src" "$tmp"
# naga's CLI has no binding map: give each resource a fixed Metal slot by name.
sed -E \
  -e 's/(constant Params& P) \[\[user\(fake0\)\]\]/\1 [[buffer(0)]]/' \
  -e 's/(texture2d<float, metal::access::sample> src) \[\[user\(fake0\)\]\]/\1 [[texture(0)]]/' \
  -e 's/(texture2d<float, metal::access::sample> luma) \[\[user\(fake0\)\]\]/\1 [[texture(1)]]/' \
  -e 's/(texture2d<float, metal::access::sample> gainmap) \[\[user\(fake0\)\]\]/\1 [[texture(2)]]/' \
  -e 's/(metal::sampler samp) \[\[user\(fake0\)\]\]/\1 [[sampler(0)]]/' \
  "$tmp" > "$tmp.bound"
if grep -q 'user(fake' "$tmp.bound"; then
  echo "unmapped shader resource:" >&2; grep -n 'user(fake' "$tmp.bound" >&2; exit 1
fi
hash=$(shasum -a 256 "$src" | cut -d' ' -f1)
{
  echo "// GENERATED by scripts/gen-shaders.sh from shaders/edit.wgsl — do not edit."
  echo "// naga $("$NAGA" --version | awk '{print $NF}')"
  echo ""
  echo "/// SHA-256 of the WGSL this was generated from (a test checks it is current)."
  echo "public let editShaderSourceHash = \"$hash\""
  echo ""
  echo "/// Metal Shading Language for the edit pipeline (compiled at runtime)."
  echo "public let editShaderMSL = #\"\"\""
  cat "$tmp.bound"
  echo "\"\"\"#"
} > "$out"
rm -f "$tmp" "$tmp.bound"
echo "wrote $out"
